package com.zenbyte.leave.controller;
import com.zenbyte.leave.entity.Employee; import com.zenbyte.leave.service.*; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/admin/reports") public class ReportController {private final EmployeeService es;private final LeaveService ls;public ReportController(EmployeeService es,LeaveService ls){this.es=es;this.ls=ls;} @GetMapping("/leave-summary") public List<Map<String,Object>> summary(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to,@RequestParam(required=false) String search){List<Employee> em=es.list(search);Map<Long,Integer> counts=ls.applicableDaysByEmployee(from,to);return em.stream().map(e->{Map<String,Object> m=new LinkedHashMap<>();m.put("employeeId",e.getEmployeeId());m.put("name",e.getName());m.put("department",e.getDepartment());m.put("leaveDays",counts.getOrDefault(e.getId(),0));return m;}).toList();}}
